import{_ as t}from"./chunks/edit-event-radio-controls.CYUZO0ec.js";import{_ as n,a as o,b as r}from"./chunks/docs-run-core-tile-sirap-listening.CfyDKkJe.js";import{c as s,Q as a,j as i,m as h}from"./chunks/framework.BqPkuuVc.js";const g="/assets/devices-manage.BiphB9sh.png",c="/assets/docs-run-core-radios.1n7hpnXE.png",d="/assets/dashboard-prime-lost.Hvmt6At0.png",l="/assets/dashboard-prime-diagnostics.B_13dw4Z.png",R=JSON.parse('{"title":"Connecting meshO Prime and radios","description":"","frontmatter":{},"headers":[],"relativePath":"user/running-the-event/connecting-prime-and-radios.md","filePath":"user/running-the-event/connecting-prime-and-radios.md"}'),p={name:"user/running-the-event/connecting-prime-and-radios.md"};function u(m,e,f,w,v,b){return a(),i("div",null,[...e[0]||(e[0]=[h('<h1 id="connecting-mesho-prime-and-radios" tabindex="-1">Connecting meshO Prime and radios <a class="header-anchor" href="#connecting-mesho-prime-and-radios" aria-label="Permalink to &quot;Connecting meshO Prime and radios&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators setting up the radio network before and during the event.</p><p><strong>meshO Prime</strong> is the hub of meshO&#39;s own radio system. You plug it into the Manager computer over USB, and it collects <strong>radio punches</strong> from <strong>meshO Control</strong> units out at the controls, plus location and status from any <strong>meshO Athlete</strong> units competitors are carrying. Those punches drive the live picture — Leaderboard, Commentary, Tracking and Live view — long before a single card is downloaded at the finish, and also help you keep track of who is still on course.</p><p>Radios are optional. Without Prime, Manager still runs the whole event from card downloads at the finish; you just don&#39;t get the live radio picture. You can also take radio punches from other timing equipment over SIRAP instead of, or as well as, Prime (see <a href="#punches-from-another-system-sirap">Punches from another system</a>). See <a href="./../what-is-mesho-manager/">How meshO Manager works</a>.</p><h2 id="switching-mesho-prime-on" tabindex="-1">Switching meshO Prime on <a class="header-anchor" href="#switching-mesho-prime-on" aria-label="Permalink to &quot;Switching meshO Prime on&quot;">​</a></h2><p>meshO Prime is switched on in two places:</p><ol><li><strong>For this computer</strong>, in <strong>Settings → Radio punches → meshO Prime</strong>: <strong>Use meshO Prime for radio punches</strong>. It is off on a new installation; turn it on here, or in the welcome tour&#39;s meshO Radios step. It is also the default for new events. While it&#39;s off, nothing in Manager offers Prime at all — no Devices page, and no Prime switch on an event.</li><li><strong>For each event</strong>, in <strong>Event details → Radio controls</strong> (the <strong><a href="./../event-setup/create-event#editing-event-details">Event details</a></strong> button at the top left of the dashboard). Under <strong>Radio controls source</strong>, switch on <strong>meshO Prime</strong>.</li></ol><p>An event only uses Prime when both are on. The radio views (<strong>Radios</strong>, <strong>Tracking</strong>, <strong>Live view</strong>) then appear in the event menu&#39;s <strong>Race</strong> mode. They can be opened before the start, and fill in once the event is live.</p><p><img src="'+t+'" alt="Event details, Radio controls tab: meshO Prime on and Accept SIRAP punches off under Radio controls source, Start, Finish and Check codes, Forward radio punches and Auto-mark controls as radio controls"></p><p>The rest of the <strong>Radio controls</strong> tab appears once the event has a source (Prime, SIRAP, or both):</p><ul><li><strong>Start codes</strong>, <strong>Finish codes</strong> and <strong>Check codes</strong> — the codes your start, finish and check units punch as, so Manager classifies those punches correctly. A code can only be in one of the three. See <a href="./../event-setup/controls-and-radio-controls#start-finish-and-check-codes">Controls and radio controls</a>. These codes are only for the start, finish and check units; to have a numbered control act as a course&#39;s start or finish instead, see <a href="./../event-setup/classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</li><li><strong>Forward radio punches</strong> — send punches on to other timing software (Prime only; see <a href="./radio-punches#forwarding-and-receiving-punches">Radio punches</a>).</li><li><strong>Auto-mark controls as radio controls</strong> — on by default. When a radio punch arrives for a course control, Manager marks that control as a radio control, so it appears on the leaderboard, Commentary and the other live views without you ticking each one.</li></ul><h2 id="connecting-prime" tabindex="-1">Connecting Prime <a class="header-anchor" href="#connecting-prime" aria-label="Permalink to &quot;Connecting Prime&quot;">​</a></h2><p>Plug meshO Prime into the Manager computer with a USB cable. <strong>Manager finds it automatically — there&#39;s no COM port to choose.</strong></p><p>To prepare the radio hardware before the event, open the <strong>Devices</strong> page: the device icon at the top of the events list. It&#39;s only there when meshO Prime is switched on in Settings and no event is live. It shows <strong>Searching for meshO Prime</strong> (&quot;Plug a meshO Prime into this computer over USB&quot;) until the unit is detected, then a <strong>Connected</strong> chip with Prime&#39;s serial number and firmware.</p><p><img src="'+g+'" alt="The meshO devices page in Manage mode, Connected: Prime, three Controls and two Athletes, with serial, kind, radio address, battery, firmware, listening, TX power, auto-standby and an actions menu on each Control"></p><p>The Devices page lists every unit Prime can hear right now — Prime itself and each meshO Control and meshO Athlete — with its <strong>Serial</strong>, <strong>Kind</strong>, <strong>Radio address</strong>, <strong>Battery</strong>, <strong>Firmware</strong>, <strong>Listening</strong>, <strong>TX power</strong>, <strong>Auto-standby</strong> and <strong>Last seen</strong>. The list starts empty each time you open the page and fills as units answer; a unit that&#39;s switched off or out of range simply isn&#39;t on it. It has two modes:</p><ul><li><strong>Manage</strong> — act on one Control from its row&#39;s menu, or tick several and use <strong>Action</strong> on all of them at once: <ul><li><strong>Identify</strong> — the unit announces itself (a beep or a flash of its light), so you can find it in a box of identical ones.</li><li><strong>Listen for radio punches</strong> / <strong>Pause listening to radio punches…</strong> — pausing saves battery on a radio left out long before the start; the Control stays on the network. Starting an event sets every radio listening again.</li><li><strong>TX power…</strong> — from <strong>Lowest</strong> to <strong>Full</strong>. Lower saves battery, higher reaches further. The level resets to full on every restart or wake-up, and most deployments don&#39;t need to change it.</li><li><strong>Enable auto-standby…</strong> / <strong>Disable auto-standby</strong> — with auto-standby on, a Control that can&#39;t hear Prime for more than 5 minutes goes to sleep, waking every 10 minutes for about a minute to look for it. Use it for radios put out well before Prime is running. While asleep it can&#39;t take punches, so allow up to 10 minutes for it to reconnect. The setting survives power cycles.</li><li><strong>Calibrate battery offset (zero current)…</strong>, <strong>Deep sleep…</strong> (until a time you choose) and <strong>Power off…</strong> (on newer boards).</li></ul></li><li><strong>Firmware</strong> — see the firmware each unit runs, update Prime over USB, and stage a Control or Athlete image on Prime to push to units over the radio network (<strong>Stage new image…</strong>, then <strong>Update…</strong> on each unit, or several at once). A unit restarts after an update and takes a minute or so to reappear.</li></ul><p>If an event goes live while the Devices page is open, Manager takes you to that event&#39;s dashboard: radio maintenance and a running event don&#39;t mix.</p><h2 id="watching-the-radio-network-during-the-event" tabindex="-1">Watching the radio network during the event <a class="header-anchor" href="#watching-the-radio-network-during-the-event" aria-label="Permalink to &quot;Watching the radio network during the event&quot;">​</a></h2><p>Once the event is live, open <strong>Radios</strong> from the event menu&#39;s <strong>Race</strong> mode. It has three panels, each folding open and shut from its coloured header:</p><p><img src="'+c+'" alt="The Radios page: the meshO Prime radio status panel open with its serial number, radio address, firmware, PCB version, last seen, punch counts, control count, uptime and GNSS location, and the meshO Athlete panel below"></p><ul><li><strong>meshO Prime radio status</strong> — <strong>Serial number</strong>, <strong>Radio address</strong>, <strong>Firmware version</strong>, <strong>PCB version</strong>, <strong>Last seen</strong> (and how long ago), <strong>Punches</strong> (<strong>Received</strong> / <strong>Stored</strong> / <strong>Unsent</strong>), <strong>Control count</strong>, <strong>Uptime</strong>, and <strong>Location (GNSS)</strong> when Prime has a GPS fix. If Prime isn&#39;t connected it says so.</li><li><strong>meshO Athlete</strong> — one row per tracker: <strong>Serial #</strong>, <strong>Radio address</strong>, <strong>Battery</strong>, <strong>Location</strong>, <strong>Location time</strong>, <strong>Firmware</strong>, <strong>PCB Ver.</strong> and <strong>Last seen</strong>.</li><li><strong>meshO Control</strong> — one row per Control: <strong>Serial #</strong>, <strong>Control #</strong> (the control code it is reporting punches as), <strong>Battery</strong>, <strong>Location</strong>, <strong>Location time</strong>, <strong>Listening</strong> (<strong>Active</strong> / <strong>Paused</strong>), <strong>TX power</strong>, <strong>Auto-standby</strong> and <strong>Last seen</strong>.</li></ul><p>Click a unit&#39;s battery for its battery history, or its location to see it on a map. Each Control&#39;s row has an actions menu — <strong>Identify</strong>, <strong>Listen for radio punches</strong> / <strong>Pause listening to radio punches…</strong>, <strong>TX power…</strong>, <strong>Enable auto-standby…</strong> / <strong>Disable auto-standby</strong>, <strong>Power off…</strong> (newer boards), and <strong>Delete…</strong>, which removes the unit and what Manager has recorded for it.</p><p>Before the event starts the page says that radios which have reported in are listed, and that commands can be sent to them once the event starts.</p><p>For an at-a-glance version, the <strong>Radio controls</strong> tile on the <a href="./dashboard">dashboard</a> shows Prime&#39;s state, a punch-activity chart for the last 30 minutes and a coloured dot per Control: green when it was heard in the last two minutes, orange when it&#39;s been quiet for two, red after five, grey if it has never been heard. The arrow at the top of the tile opens the Radios page.</p><p><img src="'+n+'" alt="The Radio controls tile: punch activity for the last 30 minutes and six meshO Controls as dots — four green, one orange, one red — with 2 low battery and 3 alerts chips"></p><p>To see the network on a map — where the Controls and trackers are and which links are working — use <a href="./live-view">Live view</a>. To plan where the radios go before the event, see <a href="./../event-setup/event-map-and-radio-placement#radio-control-placement">Radio placement</a>.</p><h3 id="battery-and-other-alerts" tabindex="-1">Battery and other alerts <a class="header-anchor" href="#battery-and-other-alerts" aria-label="Permalink to &quot;Battery and other alerts&quot;">​</a></h3><p>The <strong>Radio controls</strong> tile counts these; click its alerts chip to see them against each Control. Manager also posts them under <strong>Messages</strong> in the panel on the right of the window, and the serious ones — a critical battery, a lost connection, no location — as alerts in the <a href="./../getting-started/first-event-walkthrough#the-alerts-panel">Alerts panel</a>:</p><p><img src="'+o+'" alt="The Radio controls tile&#39;s alerts list: Battery low (21%), Weak signal, and Battery critical (4%) with Connection lost, and View all radios"></p><table tabindex="0"><thead><tr><th>Alert</th><th>When</th></tr></thead><tbody><tr><td><strong>Battery low</strong></td><td>Its battery is at 25% or less</td></tr><tr><td><strong>Battery critical</strong></td><td>Its battery is at 5% or less</td></tr><tr><td>Connection lost</td><td>It hasn&#39;t been heard for five minutes (a warning after two)</td></tr><tr><td><strong>Weak signal</strong></td><td>Its link back to Prime is poor (on the tile only)</td></tr><tr><td><strong>No location</strong></td><td>It has been on for five minutes without a GPS fix</td></tr></tbody></table><p>Treat a battery or connection alert as an early warning: change or move the unit before it costs you punches. Once the condition clears, the alert goes. Dismissing an alert in the panel stops it flashing; a fresh one appears if the condition changes again.</p><blockquote><p><strong>Recommended hardware:</strong> use SRR units (e.g. BSF8-SRR / BSF9-SRR) for the start, finish and check so both manual (contact) and contactless (SIAC &quot;air&quot;) punches are captured and broadcast live. Require a punch at the start (not a Beacon Start); a Beacon Finish is fine. See <a href="./safety-check#recommended-start-finish-hardware">Safety check</a>.</p></blockquote><h2 id="when-prime-drops-out" tabindex="-1">When Prime drops out <a class="header-anchor" href="#when-prime-drops-out" aria-label="Permalink to &quot;When Prime drops out&quot;">​</a></h2><p>If the USB cable is pulled or the connection resets during a live event, a full-screen <strong>meshO Prime connection lost</strong> notice covers the event pages while Manager waits for it to come back. Reconnect the cable — or unplug Prime and plug it back in — and Manager picks it up again automatically. <strong>Dismiss</strong> hides the notice if you need the screen in the meantime; it comes back if Prime drops out again.</p><p><img src="'+d+'" alt="meshO Prime connection lost: &quot;Connection to meshO Prime has dropped. Waiting for reconnection… Try unplugging meshO Prime and plugging it back in.&quot;, with Dismiss"></p><p>Punches Prime has received but Manager hasn&#39;t are kept in Prime&#39;s memory, and you can ask Prime to resend them. See <a href="./radio-punches#recovering-missed-punches">Recovering missed punches</a>.</p><p>If Prime isn&#39;t found at all, click <strong>Diagnostics</strong> on the dashboard&#39;s <strong>Radio controls</strong> tile. <strong>meshO Prime connection diagnostics</strong> lists the serial ports this computer can see and what Manager found on each. A port <strong>In use by another program</strong> is held by other software — close other timing software. <strong>Opened, no response</strong> means the port opened but nothing recognisable answered. <strong>No serial ports detected</strong> means the operating system doesn&#39;t see the USB device at all: check the cable. <strong>Not available</strong> shows the operating system&#39;s own reason for a port it won&#39;t open. The refresh button at the top right scans again.</p><p><img src="'+l+'" alt="meshO Prime connection diagnostics: searching, probing at 57600 baud, with COM3 Not available, COM4 Opened, no response and COM5 In use by another program"></p><h2 id="punches-from-another-system-sirap" tabindex="-1">Punches from another system (SIRAP) <a class="header-anchor" href="#punches-from-another-system-sirap" aria-label="Permalink to &quot;Punches from another system (SIRAP)&quot;">​</a></h2><p>If your radio controls are another manufacturer&#39;s, or another timing program is already collecting punches, Manager can receive them over the network using the SIRAP protocol:</p><ol><li>In <strong>Settings → Radio punches → Radio punch listening</strong>, set the <strong>Listen port</strong>.</li><li>In the event&#39;s <strong>Event details → Radio controls</strong>, switch on <strong>Accept SIRAP punches</strong>.</li><li>Point the other system at this computer&#39;s address and that port.</li></ol><p>SIRAP punches appear on the <a href="./radio-punches">Radio punches</a> page and count exactly like Prime&#39;s. The dashboard&#39;s <strong>SIRAP punch listening</strong> tile shows the port, whether Manager is <strong>Listening</strong> and how many punches it has <strong>Received</strong>.</p><p><img src="'+r+'" alt="The SIRAP punch listening tile: port 10001, Listening, 62 Received"> <strong>Radios</strong>, <strong>Tracking</strong> and <strong>Live view</strong> are Prime-only, so an event using only SIRAP doesn&#39;t show them.</p><h2 id="practising-without-a-real-event" tabindex="-1">Practising without a real event <a class="header-anchor" href="#practising-without-a-real-event" aria-label="Permalink to &quot;Practising without a real event&quot;">​</a></h2><p>For practice and testing, Manager can <strong>replay</strong> a captured event through the same path, from <strong>Replay</strong> in the event&#39;s state menu — see <a href="./dashboard#the-app-bar-the-event-s-state-and-what-to-do-next">The event dashboard</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./radio-punches">Radio punches</a> — the live feed of punches and how to act on it</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — naming radio controls and the Start/Finish/Check codes</li><li><a href="./../event-setup/event-map-and-radio-placement">The event map and radio placement</a> — planning where the radios go</li><li><a href="./live-view">Live view</a> and <a href="./tracking">Tracking</a> — the network and the trackers during the event</li><li><a href="./dashboard">The event dashboard</a> — the Radio controls tile and the live counts</li><li><a href="./safety-check">Safety check: accounting for everyone</a> — why start/finish radio coverage matters</li></ul>',48)])])}const S=s(p,[["render",u]]);export{R as __pageData,S as default};
